INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000015',1,'APPROVED','PUBLISHED',
'{"objectives":["Name fruits and vegetables in Kannada","Use X angadiyalli siguttade for availability","Shop for produce at the market"],"explanation":{"intro":"Fruits and vegetables vocabulary is essential for shopping at Karnataka''s vibrant markets and discussing food.","culturalNote":"Produce in Karnataka: Karnataka is one of India''s top horticultural states. Famous produce: Kolar Gold Fields grapes (Kolar district grapes — exported), Coorg orange (Kodagu kittale — mandarin orange — very sweet), Mysuru banana (Mysore rasabale — sweet dwarf banana), Dharwad fig (anjura — fig), Davanagere sugarcane (kabbu). Mangoes: Totapuri mango (used for juice and pickle — Karnataka''s main commercial mango), Alphanso mango (from Ratnagiri — imported), Badami mango. Vegetables: matki (field beans), avarekai (hyacinth bean — a Karnataka specialty used in sambar, palya, fried rice), seeme badnekai (cluster beans). Seasonal produce is very important — Kannadigas shop fresh daily at the nearby sabzi angadi (vegetable shop). Supermarkets (Big Basket, Reliance Fresh, More) growing but local markets still dominant."},"examples":[{"sentence":"Nanna amma pratidinaa tarkari angadige hoguttaare.","english":"My mother goes to the vegetable shop every day."},{"sentence":"Kolar drakshi thumba sihi agutte.","english":"Kolar grapes are very sweet."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name common fruits and vegetables and shop for them in Kannada."}}',
'{"items":[{"word":"tarkari","translation":"vegetables","transliteration":"tarkari","pronunciation":"tar-KA-ri","example":"tarkari angadi"},{"word":"hannu","translation":"fruit","transliteration":"hannu","pronunciation":"HAN-nu","example":"hannu tinnuttini"},{"word":"tomato","translation":"tomato","transliteration":"tomato","pronunciation":"to-MAA-to","example":"tomato palya"},{"word":"drakshi","translation":"grapes","transliteration":"drakshi","pronunciation":"DRAK-shi","example":"drakshi sihi"},{"word":"sihi","translation":"sweet","transliteration":"sihi","pronunciation":"SI-hi","example":"thumba sihi"},{"word":"kaaru","translation":"spicy/bitter/sharp","transliteration":"kaaru","pronunciation":"KAA-ru","example":"kaaru mirchi"}]}',
'{"title":"X thumba sihi/kaaru agutte — X is very sweet/spicy (taste adjectives)","pattern":"X thumba sihi agutte = X is very sweet. Sihi = sweet. Kaaru = spicy/bitter/sharp. Huli = sour. Uppu = salty. Thumba = very. Ide/agutte = is (two forms — ide for specific things at hand, agutte for general descriptions). Taste questions: eshtu sihi ide? (how sweet is it?), kaaru aguttaa? (is it spicy?).","explanation":"Taste vocabulary in Kannada: sihi (sweet), kaaru (spicy/bitter/sharp — multipurpose taste word), huli (sour — also means tamarind), uppu (salt/salty), kasa (bitter — specifically bitter), elu (no taste/bland). Questions about produce: hosa ide aa? (is it fresh?), sihi aguttaa? (is it sweet?), eshtu? (how much?). Common produce names: tomato (tomato), kaage (brinjal/eggplant), eeruLLi (onion), baLLi harave (capsicum), aalu (potato), avarekai (hyacinth beans — Karnataka specialty), drakshi (grapes), baalehanu (banana — baale = banana plant, hanu = fruit), maambalahanu (mango), kathaaLehanu (jackfruit — thumba prasiddha in coastal Karnataka).","examples":[{"sentence":"Ee onion kaaru aguttaa? — Illa, thumba sihi ide.","english":"Is this onion spicy? — No, it is very sweet."},{"sentence":"Naale baalehanu angadige baruttade.","english":"Tomorrow bananas will come to the shop."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sihi means?","options":["sweet","spicy","sour","salty"],"correctAnswer":"sweet"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Kolar grapes are very sweet.","options":["Kolar drakshi thumba sihi agutte.","Kolar drakshi thumba kaaru agutte.","Kolar baalehanu thumba sihi agutte.","Kolar drakshi thakku sihi agutte."],"correctAnswer":"Kolar drakshi thumba sihi agutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna amma pratidinaa tarkari ___ hoguttaare.","options":["angadige","angadiyalli","angadiinda","angadige"],"correctAnswer":"angadige"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Is this onion spicy? — No, it is very sweet.","wordBankItems":["Ee","onion","kaaru","aguttaa","?","—","Illa",",","thumba","sihi","ide","."],"correctAnswer":"Ee onion kaaru aguttaa ? — Illa , thumba sihi ide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hannu means?","options":["fruit","vegetable","grain","sweet"],"correctAnswer":"fruit"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000016',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about school and education in Kannada","Use naanu X school alli oduttini for studying","Discuss subjects and school life"],"explanation":{"intro":"School and education vocabulary covers classroom language, subjects, and how to talk about studying in Kannada.","culturalNote":"Education in Karnataka: Karnataka has a strong education tradition. Indian Institute of Science (IISc — Bengaluru — one of Asia''s top research universities). IIT Dharwad (new). NITs, RECs. Government schools (sarkari school — free education). Private schools (private school — English medium increasingly popular). Medium of instruction: Kannada medium vs English medium is a major political/social issue in Karnataka — parents debate which is better for their children. Navodaya Vidyalaya (residential schools — central government). Pre-university (PUC — Pre-University Certificate — Class 11-12 — important for engineering/medical admission). Engineering (engg.) and medical (MBBS) are top aspirational goals. SSLC (Secondary School Leaving Certificate) = Class 10 board exam — very important. Literacy rate: Karnataka 75%+ (national average ~74%). Kannada Rajyotsava: schools celebrate Karnataka''s birthday on November 1st."},"examples":[{"sentence":"Naanu Bengaluru alli engineering oduttini.","english":"I am studying engineering in Bengaluru."},{"sentence":"Nanna favourite subject mathematics agutte.","english":"My favourite subject is mathematics."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about school, subjects, and education in Kannada."}}',
'{"items":[{"word":"school","translation":"school","transliteration":"school","pronunciation":"skool","example":"school hoguttini"},{"word":"oduttini","translation":"I am studying (present continuous)","transliteration":"oduttini","pronunciation":"o-DUT-ti-ni","example":"naanu oduttini"},{"word":"shikshana","translation":"education","transliteration":"shikshana","pronunciation":"SHIK-sha-na","example":"channa shikshana"},{"word":"pariksha","translation":"exam","transliteration":"pariksha","pronunciation":"pa-RIK-sha","example":"pariksha baruttide"},{"word":"adhyapaka","translation":"teacher (male)","transliteration":"adhyapaka","pronunciation":"adh-YAA-pa-ka","example":"nanna adhyapaka"},{"word":"vidyaarthi","translation":"student","transliteration":"vidyaarthi","pronunciation":"vid-YAARTHI","example":"vidyaarthi iddaane"}]}',
'{"title":"Naanu X alli Y oduttini — I am studying Y at X (education statement)","pattern":"Naanu X alli Y oduttini = I am studying Y at X. Alli = at/in (location). Oduttini = I am studying (present continuous — odu = to read/study). School/college name + alli. Subject: Y = the subject. Asking: neevu elli oduttiri? (where are you studying? — formal). Completed education: naanu X alli odide (I studied at X — past tense).","explanation":"Education in Kannada: odu (to read/study — stem), oduttini (I am studying — habitual/continuous present). School year: class/standard (class + number — class hattu = class 10). University: vishvavidyaanilaya (university). Exam verbs: pariksha bareyuttini (I write the exam — bareyu = write), result hoguttide (result is coming). Result: hecchinaguttade (it has increased — pass), kommiagutte (it has decreased — fail — euphemism). Common sentences: inja school biddide (today school is a holiday — biddide = has fallen/is free). Homework: mane kaela (homework — mane = home, kaela = work).","examples":[{"sentence":"Naale pariksha ide, naanu inja oduttini.","english":"There is an exam tomorrow, I am studying today."},{"sentence":"Nanna school class hattu alli ondu nooraipatthu vidyaarthigalu iddaare.","english":"In class 10 of my school there are 120 students."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"oduttini means?","options":["I am studying","I am working","I am teaching","I am reading"],"correctAnswer":"I am studying"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am studying engineering in Bengaluru.","options":["Naanu Bengaluru alli engineering oduttini.","Naanu Mysuru alli engineering oduttini.","Naanu Bengaluru alli medicine oduttini.","Naanu Bengaluru alli engineering maaduttini."],"correctAnswer":"Naanu Bengaluru alli engineering oduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naale ___ ide, naanu inja oduttini.","options":["pariksha","school","adhyapaka","vidyaarthi"],"correctAnswer":"pariksha"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My favourite subject is mathematics.","wordBankItems":["Nanna","favourite","subject","mathematics","agutte","."],"correctAnswer":"Nanna favourite subject mathematics agutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"vidyaarthi means?","options":["student","teacher","subject","class"],"correctAnswer":"student"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000017',1,'APPROVED','PUBLISHED',
'{"objectives":["Express emotions in Kannada","Use naakke X aagutte for feeling states","Describe happiness, sadness, anger, fear"],"explanation":{"intro":"Expressing feelings and emotions covers how to describe your emotional state in Kannada — happy, sad, tired, excited, angry.","culturalNote":"Emotions in Karnataka culture: expressing emotions directly is considered less refined than hinting at them in traditional Karnataka. However, urban Bengaluru is more open to direct emotional expression influenced by global culture. Happiness: santosha (happiness — from Sanskrit santusha = contentment). Classical Kannada literature has rich emotional vocabulary — rasa theory (nava rasa = nine emotional essences: shringara=love, hasya=comedy, karuna=compassion, raudra=anger, veera=heroism, bhayanaka=fear, bibhatsa=disgust, adbhuta=wonder, shanta=peace). Pride: abhimana (pride — also used for regional pride — Kannada abhimana = pride in Kannada). Embarrassment: naachike (shame/embarrassment — naachike agutte = I feel embarrassed). Stress: tension agutte (I am stressed — English-Kannada blend — very common)."},"examples":[{"sentence":"Naakke thumba santosha aagutte.","english":"I am feeling very happy."},{"sentence":"Naakke thumba belakku aagutte.","english":"I am feeling very tired/exhausted."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express feelings and emotional states in Kannada."}}',
'{"items":[{"word":"santosha","translation":"happiness/joy","transliteration":"santosha","pronunciation":"san-TO-sha","example":"santosha aagutte"},{"word":"dukha","translation":"sadness/sorrow","transliteration":"dukha","pronunciation":"DU-kha","example":"dukha aagutte"},{"word":"kopavagutte","translation":"I am getting angry","transliteration":"kopavagutte","pronunciation":"ko-pa-va-GUT-te","example":"kopavagutte"},{"word":"bhaya","translation":"fear","transliteration":"bhaya","pronunciation":"BHA-ya","example":"bhaya aagutte"},{"word":"belakku","translation":"tiredness/exhaustion","transliteration":"belakku","pronunciation":"be-LAK-ku","example":"belakku aagutte"},{"word":"aashcharya","translation":"surprise/wonder","transliteration":"aashcharya","pronunciation":"aash-CHAR-ya","example":"aashcharya aagutte"}]}',
'{"title":"Naakke X aagutte — I am feeling X (emotion with naakke...aagutte)","pattern":"Naakke X aagutte = I am feeling X (lit. to me X is happening/becoming). Naakke = to me (dative). X = emotional state. Aagutte = is happening/becoming (present continuous of aagu). Santosha aagutte (feeling happy), dukha aagutte (feeling sad), belakku aagutte (feeling tired), bhaya aagutte (feeling afraid), kopavagutte (feeling angry — kopa = anger).","explanation":"Emotion expressions in Kannada: naakke X aagutte is the primary structure. Emotional vocabulary: santosha (happy/joy), dukha (sad/sorrow), kopa (anger), bhaya (fear), belakku (tiredness), aashcharya (surprise), naachike (embarrassment/shame), preeti (love/affection), abhimana (pride). Asking: nimage haege agutte? (how are you feeling? — formal). Response: naakke X aagutte (I am feeling X). Intensifiers: thumba (very), bahala (very — dialect), konda (a little). Strong feeling: thumba kopavagutte (I am very angry), nanna kaige X aagutte (I feel X in my hand/body — physical sensation).","examples":[{"sentence":"Result bandaaga naakke thumba santosha aayitu.","english":"When the result came I felt very happy."},{"sentence":"Nanna tamma naakke bhaya terisuttaane.","english":"My younger brother scares me."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"santosha means?","options":["happiness/joy","sadness","anger","fear"],"correctAnswer":"happiness/joy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am feeling very happy.","options":["Naakke thumba santosha aagutte.","Naakke thumba dukha aagutte.","Naakke thakku santosha aagutte.","Nimage thumba santosha aagutte."],"correctAnswer":"Naakke thumba santosha aagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naakke thumba ___ aagutte — I am very tired.","options":["belakku","santosha","dukha","bhaya"],"correctAnswer":"belakku"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: When the result came I felt very happy.","wordBankItems":["Result","bandaaga","naakke","thumba","santosha","aayitu","."],"correctAnswer":"Result bandaaga naakke thumba santosha aayitu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bhaya means?","options":["fear","anger","shame","worry"],"correctAnswer":"fear"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000018',1,'APPROVED','PUBLISHED',
'{"objectives":["Order food at a restaurant in Kannada","Use ondu X thaLi kodi for ordering","Ask for the bill and understand menu"],"explanation":{"intro":"Restaurant vocabulary covers how to order food, ask for the bill, and interact with waitstaff in Kannada — essential for eating out in Karnataka.","culturalNote":"Dining out in Karnataka: upaahara gruha (restaurant — lit. refreshment house). Meals (oota = meal/food in Kannada): beLigge oota (breakfast/morning meal), madhyaahna oota (lunch), raatri oota (dinner). Karnataka dining: meals served on banana leaf (baale ele oota) for traditional meals and festivals. Thali (thaLi — large plate with rice, sambar, rasam, vegetables, papad, pickle, buttermilk). Coffee: filtered through steel filter — served in steel tumbler-dabara set — drink by pouring between two vessels to cool and froth (davara = saucer/vessel for filter coffee). South Indian meal timing: lunch is the main meal (heaviest), dinner is lighter. Udupi restaurants: famous nationwide — vegetarian South Indian food. Darshini (quick-service standing restaurants — unique to Bengaluru — cheap, fast, idli-dosa-vade). Bill: bill kodi (give the bill — very common phrase)."},"examples":[{"sentence":"Ondu masala dosa haagu eradu idli kodi.","english":"Give me one masala dosa and two idlis."},{"sentence":"Bill eshtu aagutte?","english":"How much is the bill?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can order food and handle restaurant interactions in Kannada."}}',
'{"items":[{"word":"oota","translation":"food/meal","transliteration":"oota","pronunciation":"OO-ta","example":"oota maadide"},{"word":"thaLi","translation":"thali plate/set meal","transliteration":"thaLi","pronunciation":"THA-li","example":"ondu thaLi kodi"},{"word":"idli","translation":"idli (steamed rice cake)","transliteration":"idli","pronunciation":"ID-li","example":"eradu idli"},{"word":"bill","translation":"bill/check (restaurant)","transliteration":"bill","pronunciation":"bil","example":"bill kodi"},{"word":"kodi","translation":"give (polite imperative for ordering)","transliteration":"kodi","pronunciation":"KO-di","example":"coffee kodi"},{"word":"saakaagutte","translation":"that is enough/that will do","transliteration":"saakaagutte","pronunciation":"SAA-ka-gut-te","example":"saakaagutte, dhanyavadagalu"}]}',
'{"title":"X kodi — Please give X (restaurant ordering in Kannada)","pattern":"X kodi = Give me X (polite imperative for ordering food/items). Ondu X kodi = give me one X. Eradu X kodi = give me two X. Dayavittu X kodi = please give me X (adding dayavittu = please for politeness). Bill kodi = give me the bill. How much: bill eshtu aagutte? (how much is the bill?).","explanation":"Restaurant ordering in Kannada: kodi (give — imperative) is the key word. It is polite in a restaurant context. Add quantity: ondu, eradu, mooru before the food item. Dayavittu adds extra politeness. More: innastu kodi (give me some more). Enough: saakaagutte (that''s enough — full/satisfied). Questions: menu ide aa? (is there a menu?), veg ide aa? (is there veg?), enu special ide? (what is special today?). Calling waiter: excuse me or anna (addressing the waiter as ''brother'' — common in South India). Feedback: thumba chennaagide (it is very good!), khara aagithe (it became spicy/too spicy).","examples":[{"sentence":"Dayavittu ondu filter kaapi haagu eradu vade kodi.","english":"Please give me one filter coffee and two vadas."},{"sentence":"Oota thumba chennaagide, bill kodi.","english":"The food is very good, give me the bill."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"saakaagutte means?","options":["that is enough/that will do","please give more","it is good","I am full"],"correctAnswer":"that is enough/that will do"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Give me one masala dosa and two idlis.","options":["Ondu masala dosa haagu eradu idli kodi.","Eradu masala dosa haagu ondu idli kodi.","Ondu masala dosa haagu mooru idli kodi.","Ondu masala dosa haagu eradu vade kodi."],"correctAnswer":"Ondu masala dosa haagu eradu idli kodi."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Oota thumba chennaagide, ___ kodi.","options":["bill","kaapi","idli","thaLi"],"correctAnswer":"bill"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please give me one filter coffee and two vadas.","wordBankItems":["Dayavittu","ondu","filter","kaapi","haagu","eradu","vade","kodi","."],"correctAnswer":"Dayavittu ondu filter kaapi haagu eradu vade kodi ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"thaLi means?","options":["thali plate/set meal","plate","bowl","spoon"],"correctAnswer":"thali plate/set meal"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000019',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about the past in Kannada","Use X aayitu for completed actions","Describe what happened yesterday or last week"],"explanation":{"intro":"Talking about the past covers how to describe completed actions and past events using the past tense in Kannada.","culturalNote":"Past tense in Karnataka oral culture: storytelling (kathe = story) is a cherished tradition. Karnataka''s Yakshagana (night-long dance-drama — coastal Karnataka — stories from Mahabharata and Ramayana — male performers play female roles too — elaborate costumes). Karana (past = karana — cause — Sanskrit origin — understanding the cause/past is important philosophically). Past kings: Hyder Ali and Tipu Sultan (18th century Mysore sultans — Tipu known as Tiger of Mysore). Vijayanagara Empire (14th-16th century — golden age of Karnataka history — Hampi was capital). Daily past discussion: Indians discuss the previous day''s events, TV shows watched, cricket match results — past tense is heavily used in daily conversation."},"examples":[{"sentence":"Ninne naanu Bengaluru MG Road ge hode.","english":"Yesterday I went to MG Road in Bengaluru."},{"sentence":"Naanu inja beLigge filter kaapi kudide.","english":"I drank filter coffee this morning."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe past events using the simple past tense in Kannada."}}',
'{"items":[{"word":"ninne","translation":"yesterday","transliteration":"ninne","pronunciation":"NIN-ne","example":"ninne hode"},{"word":"hode","translation":"went (past tense of hogu)","transliteration":"hode","pronunciation":"HO-de","example":"naanu hode"},{"word":"bande","translation":"came (past tense of baa)","transliteration":"bande","pronunciation":"BAN-de","example":"avaru bande"},{"word":"maadide","translation":"did/made (past tense of maadu)","transliteration":"maadide","pronunciation":"maa-DI-de","example":"naanu maadide"},{"word":"kudide","translation":"drank (past tense of kudiyu)","transliteration":"kudide","pronunciation":"ku-DI-de","example":"kaapi kudide"},{"word":"aayitu","translation":"happened/became/finished (past — general completion)","transliteration":"aayitu","pronunciation":"aa-YI-tu","example":"kaela aayitu"}]}',
'{"title":"Naanu X de — I did X (Kannada simple past tense)","pattern":"Naanu X de = I did X (simple past, 1st person). Common past forms: hode (went), bande (came), maadide (did/made), kudide (drank), tinde (ate), nodide (saw), odide (read/studied), bareside (wrote), kelde (heard). Aayitu = it happened/finished/became (general past completion — 3rd person neuter). Duration: X aayitu (X is done/finished).","explanation":"Past tense in Kannada: 1st person past = verb stem + de (for many verbs) or -ide form. Hode (went — from hogu). Bande (came — from baa). Maadide (did — from maadu). Kudide (drank — from kudiyu). Tinde (ate — from tinnu). Nodide (saw — from nodu). Odide (read — from odu). 3rd person past: avanu hoda (he went), avalu bande (she came), avaru banda/hoda (they/formal came/went). Aayitu = it happened/completed (neuter 3rd person past of aagu — very versatile for describing completed events). Past with time: ninne (yesterday), irene (day before yesterday), haLe (ago/old), X din/hafte/varsha hindhe (X days/weeks/years ago).","examples":[{"sentence":"Naanu ninne Dasara prabhate nodide.","english":"Yesterday I watched the Dasara procession."},{"sentence":"Pariksha chennaagide — result yaavattu baruttade?","english":"The exam went well — when will the result come?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"hode means?","options":["went (past of hogu)","came","ate","did"],"correctAnswer":"went (past of hogu)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Yesterday I went to MG Road in Bengaluru.","options":["Ninne naanu Bengaluru MG Road ge hode.","Inja naanu Bengaluru MG Road ge hode.","Ninne naanu Mysuru MG Road ge hode.","Ninne avanu Bengaluru MG Road ge hoda."],"correctAnswer":"Ninne naanu Bengaluru MG Road ge hode."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu inja beLigge filter kaapi ___ .","options":["kudide","kudiyuttini","kudiyttide","kudittu"],"correctAnswer":"kudide"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Yesterday I watched the Dasara procession.","wordBankItems":["Naanu","ninne","Dasara","prabhate","nodide","."],"correctAnswer":"Naanu ninne Dasara prabhate nodide ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aayitu means?","options":["happened/finished (past completion)","will happen","is happening","happens always"],"correctAnswer":"happened/finished (past completion)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000001a',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about future plans in Kannada","Use naanu X uttini for future intentions","Discuss upcoming events and plans"],"explanation":{"intro":"Making plans and future tense covers how to express future intentions and upcoming activities in Kannada.","culturalNote":"Planning in Karnataka: muhurta (auspicious timing — selected by an astrologer — important for weddings, starting new ventures, moving to a new home). Planning around festivals: Dasara (October), Ugaadi (March/April), Diwali (October/November) — major events are planned months in advance. IT project planning: Bengaluru''s tech culture uses planning terms — roadmap, sprint, deadline — mixed with Kannada. Weekend plans (weekend plans) are a common topic in urban Bengaluru — road trip to Coorg, Hampi, Mysuru. Road trips: Bengaluru to Mysuru (140km — 3 hours), Bengaluru to Coorg (250km — 5 hours), Bengaluru to Hampi (340km — 6 hours). Plan phrasing: plan maadiddini (I have made a plan), hoga beku (I need to go), hogona (let''s go)."},"examples":[{"sentence":"Naale naanu Mysuru ge hoguttini.","english":"Tomorrow I am going to Mysuru."},{"sentence":"Nantara vaara naanu Coorg ge hoguvenu.","english":"Next week I will go to Coorg."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about future plans and intentions in Kannada."}}',
'{"items":[{"word":"naale","translation":"tomorrow","transliteration":"naale","pronunciation":"NAA-le","example":"naale hoguttini"},{"word":"nantara vaara","translation":"next week","transliteration":"nantara vaara","pronunciation":"NAN-ta-ra VAA-ra","example":"nantara vaara"},{"word":"hoguttini","translation":"I am going (present/future)","transliteration":"hoguttini","pronunciation":"ho-GUT-ti-ni","example":"naale hoguttini"},{"word":"plan","translation":"plan","transliteration":"plan","pronunciation":"plan","example":"plan maadide"},{"word":"hogona","translation":"let''s go","transliteration":"hogona","pronunciation":"ho-GO-na","example":"hogona baa"},{"word":"beku","translation":"need to/want to/should","transliteration":"beku","pronunciation":"BE-ku","example":"hoga beku"}]}',
'{"title":"Naanu X ge hoguttini — I am going to X (future with present form in Kannada)","pattern":"Naanu X ge hoguttini = I am going to X (present tense used for near future — same as English). Ge = to (directional suffix). Hoguttini = I go/am going (present habitual/continuous — also future in context). Future emphasis: hoguvenu (I will go — explicit future). Naale (tomorrow), nantara vaara (next week), nantara thinnga (next month). Let''s: hogona (let''s go — hortative of hogu).","explanation":"Future in Kannada: present tense form (hoguttini) is commonly used for near future intentions — same as English ''I am going to Mysuru tomorrow.'' More explicit future: hoguvenu (I will go — explicit future 1st person), baruvenu (I will come), maaduvenu (I will do). Beku = need to/must (obligation): naanu X ge hoga beku (I need/must go to X). Plans: plan maadiddini (I have made a plan — already planned). Intentions: naanu X maadabeku anta iddini (I have in mind to do X). Hortative (let''s): hogona (let''s go), maadona (let''s do), nodona (let''s see).","examples":[{"sentence":"Naanu naale doctor hattira hoguttini.","english":"Tomorrow I am going to the doctor."},{"sentence":"Namma iduvella Coorg ge hogona — haege ide?","english":"Let''s all go to Coorg — how is that?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"beku means?","options":["need to/want to/should","will/shall","let''s","going to"],"correctAnswer":"need to/want to/should"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tomorrow I am going to Mysuru.","options":["Naale naanu Mysuru ge hoguttini.","Ninne naanu Mysuru ge hoguttini.","Naale naanu Bengaluru ge hoguttini.","Naale avanu Mysuru ge hoguttaane."],"correctAnswer":"Naale naanu Mysuru ge hoguttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma iduvella Coorg ge ___ — haege ide?","options":["hogona","hoguttini","hoguvenu","hogabeku"],"correctAnswer":"hogona"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Next week I will go to Coorg.","wordBankItems":["Nantara","vaara","naanu","Coorg","ge","hoguvenu","."],"correctAnswer":"Nantara vaara naanu Coorg ge hoguvenu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hogona means?","options":["let''s go","let''s come","I will go","you go"],"correctAnswer":"let''s go"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000001b',1,'APPROVED','PUBLISHED',
'{"objectives":["Ask for permission and help in Kannada","Use naanu X maadabahudu aa? for permission requests","Politely ask for assistance"],"explanation":{"intro":"Asking for permission and help covers the polite forms used to request permission to do something or ask for assistance from others.","culturalNote":"Politeness in Kannada: Kannada has distinct politeness levels. Formal/respectful: -iri endings (hogiri = please go, banni = please come). Semi-formal: -i ending (hogi = go, baa = come). Informal: -u/-o ending (hogu/hog = go, baa = come). Elders and strangers: always use formal forms — this shows respect (gaurava). Seniors at work: -avaru/-iru endings. Help (sahaya): dayavittu naage sahaya maadi (please help me — sahaya maadu = to help). Permission: naanu X maadabahudu aa? (may I do X? — bahudu = may/might + aa = question marker). Common social helping: nabours helping each other, auto drivers giving directions, shopkeepers going out of their way to help — Karnataka known for being helpful to strangers."},"examples":[{"sentence":"Naanu illi kuLitura bahudu aa?","english":"May I sit here?"},{"sentence":"Dayavittu naage sahaya maadi.","english":"Please help me."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask for permission and help politely in Kannada."}}',
'{"items":[{"word":"bahudu","translation":"may/might/can (permission)","transliteration":"bahudu","pronunciation":"ba-HU-du","example":"hogabahudu aa?"},{"word":"sahaya","translation":"help/assistance","transliteration":"sahaya","pronunciation":"SA-ha-ya","example":"sahaya maadi"},{"word":"dayavittu","translation":"please (polite request)","transliteration":"dayavittu","pronunciation":"da-ya-VIT-tu","example":"dayavittu kodi"},{"word":"illi","translation":"here","transliteration":"illi","pronunciation":"IL-li","example":"illi baa"},{"word":"allli","translation":"there","transliteration":"alli","pronunciation":"AL-li","example":"alli ide"},{"word":"gottilla","translation":"I don''t know","transliteration":"gottilla","pronunciation":"got-TIL-la","example":"naakke gottilla"}]}',
'{"title":"X maadabahudu aa? — May I do X? (permission request in Kannada)","pattern":"Naanu X maadabahudu aa? = May I do X? Maadabahudu = may do (maadu + a bahudu = the ''may'' form — verbal noun form + bahudu). Aa = question particle. Simple permission: X maadabahudu (you may do X — granting permission). Polite help request: dayavittu X maadi (please do X — dayavittu = please).","explanation":"Permission in Kannada: X maadabahudu = X may be done / you may do X. To ask: naanu X maadabahudu aa? (may I do X?). To grant: howdu, maadabahudu (yes, you may). To refuse: illa, maadabaradu (no, you may not — baradu = must not). Polite requests: dayavittu X kodi (please give X), dayavittu X maadi (please do X). Asking for help: naakke X maadodakke sahaya beku (I need help to do X — a more elaborate request form). Common permission situations: naanu hogabahudu aa? (may I go?), naanu illi kuLitura bahudu aa? (may I sit here?), naanu phone maadabahudu aa? (may I make a phone call?).","examples":[{"sentence":"Naanu ee chair takkondogu bahudu aa?","english":"May I take/use this chair?"},{"sentence":"Dayavittu naage raaste torsuttiri aa?","english":"Please, will you show me the way?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"dayavittu means?","options":["please (polite request)","thank you","sorry","excuse me"],"correctAnswer":"please (polite request)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"May I sit here?","options":["Naanu illi kuLitura bahudu aa?","Naanu alli kuLitura bahudu aa?","Naanu illi hogabahudu aa?","Neevu illi kuLitura bahudu aa?"],"correctAnswer":"Naanu illi kuLitura bahudu aa?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dayavittu naage sahaya ___ .","options":["maadi","kodi","baa","hogi"],"correctAnswer":"maadi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please, will you show me the way?","wordBankItems":["Dayavittu","naage","raaste","torsuttiri","aa","?"],"correctAnswer":"Dayavittu naage raaste torsuttiri aa ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bahudu means?","options":["may/might/can (permission)","must","should","will"],"correctAnswer":"may/might/can (permission)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000001c',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about sports and hobbies in Kannada","Use naanu X aaduttini for playing sports","Describe leisure activities"],"explanation":{"intro":"Sports and hobbies vocabulary covers leisure activities, games, and how to talk about what you enjoy doing in your free time in Kannada.","culturalNote":"Sports in Karnataka: cricket (most popular — RCB = Royal Challengers Bangalore — IPL team — huge fan following). Chinnaswamy Stadium (Bengaluru''s cricket stadium). Kabaddi (traditional contact sport — Pro Kabaddi League popular — Bengaluru Bulls). Football: Bengaluru FC (popular football club). Kho-kho (traditional tag sport). Chess: Viswanathan Anand (Tamil Nadu) inspired chess in South India. Badminton: Prakash Padukone (Bengaluru — India''s first All-England champion), Saina Nehwal (nearby). Wrestling: traditional kushti (wrestling). Karnataka athletics: Ashwini Nachappa (sprinter from Coorg). Hobbies: photography (fotografi), cooking (aduge maadu), music (sangeetha), yoga (yoga maadu), trekking (trekking — Western Ghats trails very popular from Bengaluru). Weekend activities: trek hoguttini (going trekking), coffee estate visit (Coorg), temple visit (Udupi, Dharmasthala)."},"examples":[{"sentence":"Naanu pratidinaa cricket aaduttini.","english":"I play cricket every day."},{"sentence":"Nanna hobby photography haagu trekking.","english":"My hobby is photography and trekking."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about sports and hobbies in Kannada."}}',
'{"items":[{"word":"aaduttini","translation":"I play (habitual present)","transliteration":"aaduttini","pronunciation":"aa-DUT-ti-ni","example":"cricket aaduttini"},{"word":"nadeyuttini","translation":"I walk (habitual present)","transliteration":"nadeyuttini","pronunciation":"na-de-YUT-ti-ni","example":"pratidinaa nadeyuttini"},{"word":"oduttini","translation":"I read/study (habitual present)","transliteration":"oduttini","pronunciation":"o-DUT-ti-ni","example":"book oduttini"},{"word":"sangeetha","translation":"music","transliteration":"sangeetha","pronunciation":"san-GEE-tha","example":"sangeetha keLayuttini"},{"word":"hobby","translation":"hobby","transliteration":"hobby","pronunciation":"HOB-bi","example":"nanna hobby"},{"word":"bikaDi","translation":"free time/leisure","transliteration":"bikaDi","pronunciation":"bi-KA-di","example":"bikaDi samaya"}]}',
'{"title":"Naanu X aaduttini — I play X (sport/game habitual present)","pattern":"Naanu X aaduttini = I play X (habitual). Aadu = to play (games/sports). Aaduttini = I play (1st person habitual present — -uttini suffix). Naanu X hoguttini = I go X (for outdoor activities — trek hoguttini = I go trekking). Naanu X oduttini = I read X. Naanu X keLayuttini = I listen to X (kelayu = to listen/hear).","explanation":"Leisure verbs in Kannada: aadu (play — games and sports), naDeyu (walk), odu (read/study), bareyuttini (I write), kelayu (listen), nodu (watch/see), haadu (sing), kali (dance). Habitual present: stem + uttini (1st person). Activities: cricket/football aaduttini (I play cricket/football), yoga maaduttini (I do yoga), sangeetha keLayuttini (I listen to music), TV noduttini (I watch TV), pushpaka odu (read a book — pushpaka = book/tome). Free time: bikaDi samayalli (in my free time). How often: pratidinaa (every day), shani/bhanu vaara (on Saturday/Sunday), saanjeyalli (in the evening).","examples":[{"sentence":"Saanjeyalli naanu park alli naadeyuttini.","english":"In the evening I walk in the park."},{"sentence":"Bikadiyalli naanu Kannada pustaka oduttini.","english":"In my free time I read Kannada books."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"aaduttini means?","options":["I play (habitual)","I work","I walk","I go"],"correctAnswer":"I play (habitual)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I play cricket every day.","options":["Naanu pratidinaa cricket aaduttini.","Naanu pratidinaa football aaduttini.","Naanu pratidinaa cricket naadeyuttini.","Naanu kabhi-kabhi cricket aaduttini."],"correctAnswer":"Naanu pratidinaa cricket aaduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bikadiyalli naanu Kannada pustaka ___ .","options":["oduttini","aaduttini","nadeyuttini","hoguttini"],"correctAnswer":"oduttini"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In the evening I walk in the park.","wordBankItems":["Saanjeyalli","naanu","park","alli","nadeyuttini","."],"correctAnswer":"Saanjeyalli naanu park alli nadeyuttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sangeetha means?","options":["music","dance","sport","hobby"],"correctAnswer":"music"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000001d',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about Karnataka festivals in Kannada","Use X habba bandide for festival announcements","Describe how festivals are celebrated"],"explanation":{"intro":"Karnataka festivals vocabulary covers the major celebrations of the state and how to discuss them in Kannada.","culturalNote":"Karnataka festivals: Dasara (most famous — Mysuru Dasara = state festival — 10-day celebration — Vijayadashami — goddess Chamundeshwari — grand procession with 60+ decorated elephants, golden howdah elephant, lights up entire Mysuru — UNESCO intangible heritage — held in October). Ugaadi (Karnataka/Andhra New Year — first day of Chaitra month — March/April — new beginnings — bevu-bella = neem + jaggery eaten together = life is sweet and bitter). Sankranti (harvest festival — January 14 — kite flying — ellu-bella (sesame-jaggery) shared among neighbours — sesame seeds = friendship). Diwali (festival of lights — October/November). Karaga (Bengaluru''s unique festival — Thigala community — 3-day festival — priest carries karaga on head — long tradition in Bengaluru). Nada Habba (state festival of Karnataka — November 1 = Kannada Rajyotsava = state birthday). Hampi Utsava (music/dance festival at Hampi ruins — November)."},"examples":[{"sentence":"Inja Ugaadi habba — shubhashayagalu!","english":"Today is Ugaadi festival — happy festival wishes!"},{"sentence":"Dasara samaya Mysuru thumba channagide.","english":"During Dasara time Mysuru is very beautiful."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about Karnataka festivals and how they are celebrated in Kannada."}}',
'{"items":[{"word":"habba","translation":"festival/celebration","transliteration":"habba","pronunciation":"HAB-ba","example":"habba bandide"},{"word":"Dasara","translation":"Dasara (Karnataka''s biggest festival)","transliteration":"Dasara","pronunciation":"DA-sa-ra","example":"Dasara habba"},{"word":"Ugaadi","translation":"Ugaadi (Kannada New Year)","transliteration":"Ugaadi","pronunciation":"u-GAA-di","example":"Ugaadi habba"},{"word":"shubhashayagalu","translation":"best wishes/congratulations","transliteration":"shubhashayagalu","pronunciation":"shubh-aa-SHA-ya-ga-lu","example":"habba shubhashayagalu"},{"word":"hana","translation":"money/wealth (also used for prize at festival)","transliteration":"hana","pronunciation":"HA-na","example":"hana kodi"},{"word":"alankara","translation":"decoration/ornamentation","transliteration":"alankara","pronunciation":"a-LAN-ka-ra","example":"alankara maaduttaare"}]}',
'{"title":"X habba bandide — X festival has come (festival announcement)","pattern":"X habba bandide = X festival has come (present perfect — bandide = has come). Habba = festival. Habba maadutte = we celebrate the festival. X samaya = the time of X. Greetings: X habba shubhashayagalu (festival greetings/wishes for X). How it is celebrated: X maaduttaare (they do X), alankaara maaduttaare (they decorate).","explanation":"Festival language in Kannada: habba (festival), mela (fair/event), utsava (celebration/festival — more formal). Announcing: X habba bandide (X festival has come/arrived). Greeting: X habba shubhashayagalu (happy X festival — shubhashayagalu = auspicious wishes). Celebrating: Dasara habba maadutte (we celebrate Dasara), habbada oota maaduttini (I cook a festival meal). Traditional foods at festivals: obbattu/holige (sweet flatbread for Ugaadi), boorelu (sweets for Dasara), ellu-bella (sesame-jaggery for Sankranti). Describing: thumba chandagide (it is very beautiful/splendid — chandagide slightly stronger than chennagide).","examples":[{"sentence":"Dasara samaya Mysuru alli deeepagalinda alankara maaduttaare.","english":"During Dasara in Mysuru they decorate with lights."},{"sentence":"Ugaadi ge namma mane alli bevu-bella tinnuttivi.","english":"For Ugaadi we eat neem-jaggery at our house."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"habba means?","options":["festival/celebration","procession","prayer","decoration"],"correctAnswer":"festival/celebration"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today is Ugaadi festival — happy festival wishes!","options":["Inja Ugaadi habba — shubhashayagalu!","Inja Dasara habba — shubhashayagalu!","Naale Ugaadi habba — shubhashayagalu!","Inja Ugaadi habba — dhanyavadagalu!"],"correctAnswer":"Inja Ugaadi habba — shubhashayagalu!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dasara samaya Mysuru thumba ___ .","options":["channagide","sihi agutte","doora ide","hosa agutte"],"correctAnswer":"channagide"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: During Dasara in Mysuru they decorate with lights.","wordBankItems":["Dasara","samaya","Mysuru","alli","deeepagalinda","alankara","maaduttaare","."],"correctAnswer":"Dasara samaya Mysuru alli deeepagalinda alankara maaduttaare ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"shubhashayagalu means?","options":["best wishes/congratulations","thank you","hello","goodbye"],"correctAnswer":"best wishes/congratulations"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000001e',1,'APPROVED','PUBLISHED',
'{"objectives":["Review core A1 Kannada grammar structures","Consolidate key vocabulary from lessons 1-29","Practice with comprehensive A1 exercises"],"explanation":{"intro":"A1 review consolidates the most important Kannada grammar structures and vocabulary from the first 29 lessons.","culturalNote":"Kannada A1 achievement summary: completing this level means you can greet people (Namaskara), introduce yourself, navigate a market (angadi), order food (kodi), ask for directions (eliide), describe your family (nanna amma/appa), talk about your daily routine (pratidinaa), discuss your hobbies, describe places, and talk about festivals. You know Karnataka''s geography (Bengaluru, Mysuru, Coorg, Hampi), its food (filter kaapi, bisi bele bath, ragi mudde), and its culture (Dasara, Ugaadi). Core grammar mastered: naanu X iddini (I am X), naanu X maaduttini (I do X — habitual), naanu X maadide (I did X — past), naakke X aagutte (I feel/experience X — dative), X alli Y ide (Y is in X — locative), X ge hoguttini (I go to X — directional), question words (yaaru/enu/elli/eshtu/howdu/illa). Moving to A2: compound sentences, more verb forms, reported speech, and richer conversational vocabulary."},"examples":[{"sentence":"Namaskara, naanu Amit, naanu Bengalurualli software engineer kaela maaduttini.","english":"Hello, I am Amit, I work as a software engineer in Bengaluru."},{"sentence":"Naakke Kannada kelarattittu, eedannu naanu chennaagide.","english":"I wanted to learn Kannada, and now I have learned it well."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have completed Kannada A1 — I can communicate in Kannada on basic everyday topics."}}',
'{"items":[{"word":"maaduttini","translation":"I do (habitual 1st person — core A1 verb form)","transliteration":"maaduttini","pronunciation":"maa-DUT-ti-ni","example":"kaela maaduttini"},{"word":"ide","translation":"is/there is (present 3rd — core A1 be verb)","transliteration":"ide","pronunciation":"I-de","example":"maneyalli ide"},{"word":"aagutte","translation":"it becomes/is (process/description)","transliteration":"aagutte","pronunciation":"aa-GUT-te","example":"eshtu aagutte?"},{"word":"naakke","translation":"to me (dative — key for emotions and liking)","transliteration":"naakke","pronunciation":"NAAK-ke","example":"naakke ishtavagutte"},{"word":"howdu","translation":"yes","transliteration":"howdu","pronunciation":"HOW-du","example":"howdu, sari"},{"word":"keli","translation":"learn/heard/called (stem of kali — to learn)","transliteration":"kali","pronunciation":"KA-li","example":"Kannada kali"}]}',
'{"title":"Kannada A1 core structure review — all 10 key patterns","pattern":"(1) Naanu X iddini = I am X. (2) Naanu X maaduttini = I do X (habitual). (3) Naanu X maadide = I did X (past). (4) Naakke X ishtavagutte = I like X. (5) Naakke X aagutte = I feel X (emotion). (6) X alli Y ide = Y is in X (location). (7) X ge hoguttini = I go to X. (8) X eshtu? / X aagutte? = how much? / what will it cost? (9) Howdu / illa = yes / no. (10) X kodi = give me X (ordering/requesting).","explanation":"Kannada A1 grammar toolkit: ten core patterns cover: identity (1), habitual action (2), past action (3), liking/emotion (4-5), location (6), direction (7), price/quantity (8), yes/no (9), requesting (10). Gender/agreement: Kannada verbs agree with grammatical person and formal/informal register — not with gender of noun (unlike Hindi). Formal endings (-iri/-aare) vs informal endings (-iya/-aane/-aaLe). Cultural competency: greet with Namaskara, use dayavittu for requests, say dhanyavadagalu for thanks, howdu for yes, illa for no. Next level (A2): compound sentences, conditional (aadare = but, agi = so/thus), comparatives (X se/ginte Y zyaada — X more than Y), reported speech.","examples":[{"sentence":"Naanu Bengaluruinda, IT company alli kaela maaduttini, naakke Kannada kelarattitu.","english":"I am from Bengaluru, I work at an IT company, I wanted to learn Kannada."},{"sentence":"Illi kuLitu, filter kaapi kudi, naale neevu Kannada matthaade maaduttiri?","english":"Sit here, drink filter coffee, will you speak more Kannada tomorrow?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"naakke X ishtavagutte means?","options":["I like X","I need X","I feel X","I want X"],"correctAnswer":"I like X"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Hello, I am Amit, I work as a software engineer in Bengaluru.","options":["Namaskara, naanu Amit, naanu Bengalurualli software engineer kaela maaduttini.","Namaskara, naanu Amit, naanu Mysuralli software engineer kaela maaduttini.","Namaskara, avanu Amit, avanu Bengalurualli software engineer kaela maaduttaane.","Namaskara, naanu Amit, naanu Bengalurualli doctor kaela maaduttini."],"correctAnswer":"Namaskara, naanu Amit, naanu Bengalurualli software engineer kaela maaduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu park ge ___ — Namaskara kodi.","options":["hoguttini","hode","baruttini","iddini"],"correctAnswer":"hoguttini"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am from Bengaluru and I work at an IT company.","wordBankItems":["Naanu","Bengaluruinda",",","IT","company","alli","kaela","maaduttini","."],"correctAnswer":"Naanu Bengaluruinda , IT company alli kaela maaduttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"howdu means?","options":["yes","no","maybe","okay"],"correctAnswer":"yes"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

